const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'workspaceId', 'userId', 'input', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

const brief = body.input;
if (!brief || brief.reportType !== 'manager_summary') {
  throw new Error('input.reportType doit valoir "manager_summary" pour ce workflow');
}
if (!brief.period || !brief.period.startDate || !brief.period.endDate) {
  throw new Error('input.period.startDate et endDate sont requis');
}
if (!brief.facts || typeof brief.facts !== 'object') {
  throw new Error('input.facts est requis — ce workflow ne calcule aucun fait, il attend que Next.js les ait assemblés via get_manager_summary_facts.');
}

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    brief: brief,
    callbackUrl: body.callbackUrl,
  }
}];

const briefData = $('Validate Brief').item.json;
const brief = briefData.brief;
const facts = brief.facts;

const SYSTEM_PROMPT = `Tu rédiges le Compte-rendu Manager pour un manager d'ESN premium (Kredo Digital).
Ce document est une note exécutive de synthèse d'activité et de pilotage.

RÈGLES ABSOLUES :
1. Tu reçois un dictionnaire de FAITS déjà calculés (JSON ci-dessous). Ce sont les SEULES données chiffrées et les SEULS éléments individuels que tu as le droit de citer. Tu ne dois JAMAIS inventer un chiffre, une date, un nom de compte/opportunité/mission/candidat absent des FAITS.
2. Si une donnée est absente (ex: aucun RDV, aucune opportunité), dis-le simplement et sobrement sans inventer.
3. Style : direct, synthétique, orienté décision et résultat, sans superlatifs creux. Utilise exclusivement la terminologie du Compte-rendu Manager.

FORMAT DE SORTIE :
Réponds UNIQUEMENT en JSON valide, sans backticks, structure obligatoire :
{
  "executiveSummary": "3 à 5 lignes : la synthèse globale de la semaine",
  "commercialCommentary": "Commentaire analytique concis sur l'activité commerciale",
  "recruitmentCommentary": "Commentaire analytique sur l'activité recrutement",
  "signatureConvictionCommentary": "Commentaire sur l'opportunité/compte phare en conviction de signature",
  "strategyProgression": "Avancement et commentaires sur l'objectif stratégique en cours"
}`;

const detailLevel = brief.detailLevel || 'standard';
const instructions = brief.additionalInstructions || '(aucune)';

const userPrompt = `NIVEAU DE DÉTAIL : ${detailLevel}
INSTRUCTIONS COMPLÉMENTAIRES : ${instructions}

FAITS (source unique de vérité — JSON) :
${JSON.stringify(facts, null, 2)}`;

return [{
  json: {
    ...briefData,
    facts,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt,
  }
}];

