={{ {
  model: "claude-sonnet-5",
  max_tokens: 3000,
  thinking: { type: "disabled" },
  system: $json.systemPrompt,
  messages: [ { role: "user", content: $json.userPrompt } ]
} }}

parameters.jsCode:
const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Réponse LLM non-JSON : ' + content.slice(0, 200));
}

if (!parsed.executiveSummary || parsed.executiveSummary.length < 20) {
  throw new Error('executiveSummary vide ou trop courte');
}
if (
  typeof parsed.commercialCommentary !== 'string' ||
  typeof parsed.recruitmentCommentary !== 'string' ||
  typeof parsed.signatureConvictionCommentary !== 'string' ||
  typeof parsed.strategyProgression !== 'string'
) {
  throw new Error('Champs narratifs obligatoires du Compte-rendu Manager manquants');
}

return [{
  json: {
    ...upstream,
    narrative: parsed,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

const data = $input.first().json;
const narrative = data.narrative;
const factsStr = JSON.stringify(data.facts);
const qaFlags = [];

const narrativeText = [
  narrative.executiveSummary,
  narrative.commercialCommentary,
  narrative.recruitmentCommentary,
  narrative.signatureConvictionCommentary,
  narrative.strategyProgression,
].filter(Boolean).join(' ');

const numbers = narrativeText.match(/\d{2,}/g) || [];
const unauthorized = numbers.filter((n) => !factsStr.includes(n));
if (unauthorized.length > 0) {
  qaFlags.push({ check: 'no_unauthorized_numbers', passed: false, detail: `Nombres absents des FAITS : ${unauthorized.join(', ')}` });
} else {
  qaFlags.push({ check: 'no_unauthorized_numbers', passed: true });
}

const summaryWordCount = (narrative.executiveSummary || '').split(/\s+/).filter(Boolean).length;
if (summaryWordCount < 15 || summaryWordCount > 150) {
  qaFlags.push({ check: 'summary_length', passed: false, detail: `${summaryWordCount} mots (attendu 15-150)` });
} else {
  qaFlags.push({ check: 'summary_length', passed: true, detail: `${summaryWordCount} mots` });
}

const priorities = Array.isArray(data.facts.nextWeek?.priorities) ? data.facts.nextWeek.priorities : [];
if (priorities.length > 0) {
  qaFlags.push({ check: 'top_priorities_traceability', passed: true, detail: `${priorities.length} priorités S+1 traçables` });
} else {
  qaFlags.push({ check: 'top_priorities_traceability', passed: false, detail: 'Aucune priorité disponible dans facts.nextWeek.priorities' });
}

if (data.facts.caveats && data.facts.caveats.length > 0) {
  qaFlags.push({ check: 'data_coverage_caveats', passed: true, detail: data.facts.caveats.join(' | ') });
}

return [{ json: { ...data, qaFlags } }];

const data = $input.first().json;

const contentJson = {
  facts: data.facts,
  narrative: data.narrative,
  sourceRefs: (data.facts.nextWeek?.priorities || []).map((p) => ({ entityType: 'opportunity', label: p.title })),
  qaFlags: data.qaFlags || [],
};

const period = data.facts.period || {};
const startDate = period.startDate || '';
const title = `Compte-rendu Manager — Semaine du ${startDate}`;

const priorities = Array.isArray(data.facts.nextWeek?.priorities) ? data.facts.nextWeek.priorities : [];
const prioritiesText = priorities.length > 0
  ? priorities.map((p, idx) => `${idx + 1}. ${p.title} — ${p.description || ''}${p.nextAction ? ` (Prochaine action : ${p.nextAction})` : ''}`).join('\n')
  : 'Aucune activité enregistrée';

const declaredDifficulties = data.facts.declared?.difficulties;
const declaredRequests = data.facts.declared?.specificRequests;
const declaredText = [declaredDifficulties ? `Difficultés : ${declaredDifficulties}` : null, declaredRequests ? `Demandes spécifiques : ${declaredRequests}` : null].filter(Boolean).join('\n') || 'Aucune activité enregistrée';

const strategicFocus = data.facts.strategy?.strategicFocus;
const strategyProgression = data.narrative?.strategyProgression;
const strategyText = [strategicFocus ? `Focus : ${strategicFocus}` : null, strategyProgression ? `Avancement : ${strategyProgression}` : null].filter(Boolean).join('\n') || 'Aucune activité enregistrée';

const contentTextParts = [
  `# ${title}`,
  `## 1. Synthèse\n${data.narrative.executiveSummary}`,
  `## 2. Activité commerciale\n${data.narrative.commercialCommentary}`,
  `## 3. Recrutement\n${data.narrative.recruitmentCommentary}`,
  `## 4. Conviction signature\n${data.narrative.signatureConvictionCommentary}`,
  `## 5. Sujets prioritaires & next steps\n${prioritiesText}`,
  `## 6. Difficultés / demandes spécifiques\n${declaredText}`,
  `## 7. Stratégie en cours\n${strategyText}`,
];

const hasFailedQA = (data.qaFlags || []).some((f) => f.passed === false);
const status = hasFailedQA ? 'failed' : 'succeeded';

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId: data.runId,
  phase: 1,
  resultType: 'manager_summary',
  status,
  contentJson,
  contentText: contentTextParts.join('\n\n'),
  title,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.facts,
  sourceRefs: contentJson.sourceRefs,
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

try {
  const vb = $('Validate Brief').item.json;
  runId = vb.runId || null;
  callbackUrl = vb.callbackUrl || null;
} catch (e) {
  // Validate Brief n'a produit aucune sortie exploitable — notification impossible.
}

let errorMessage = 'Erreur inconnue dans le workflow report-manager-summary';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId,
  phase: 1,
  resultType: 'manager_summary',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
